<template><BaseModal v-model="visible" size="lg" :close-disabled="loading" :close-on-esc="!loading" :close-on-overlay-click="!loading"><template #header><div class="title"><h2>{{overhead?'ویرایش هزینه سربار':'هزینه سربار جدید'}}</h2><p v-if="overhead">{{overhead.title}}</p></div></template><form id="overhead-form" dir="rtl" novalidate @submit.prevent="submit"><div v-if="serverError" class="error">{{serverError}}</div><div class="grid"><label class="wide">عنوان <b>الزامی</b><input ref="titleInput" v-model.trim="form.title" maxlength="120" placeholder="مثلاً اجاره ماهانه"/><em v-if="errors.title">{{errors.title}}</em></label><label>نوع هزینه <b>الزامی</b><select v-model="form.kind"><option v-for="item in kinds" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></label><label>مبلغ (تومان) <b>الزامی</b><input v-model="form.amount" type="number" min="0.01" step="0.01" inputmode="decimal"/><em v-if="errors.amount">{{errors.amount}}</em></label><label>تاریخ هزینه <b>الزامی</b><JalaliDatePicker v-model="form.expense_date" :clearable="false"/><em v-if="errors.expense_date">{{errors.expense_date}}</em></label><label>روش تخصیص <b>الزامی</b><select v-model="form.allocation_method"><option v-for="item in allocations" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></label><label class="wide">توضیحات <b>اختیاری</b><textarea v-model.trim="form.description" rows="3" maxlength="500"></textarea></label><label class="active wide"><span><strong>هزینه فعال باشد</strong><small>فقط هزینه فعال در محاسبه بهای تولید استفاده می‌شود.</small></span><input v-model="form.is_active" type="checkbox"/></label></div></form><template #footer><button class="secondary" :disabled="loading" @click="visible=false">انصراف</button><button class="primary" form="overhead-form" :disabled="loading">{{loading?'در حال ذخیره…':overhead?'ذخیره تغییرات':'ایجاد هزینه'}}</button></template></BaseModal></template>
<script setup>import{computed,nextTick,reactive,ref,watch}from'vue';import BaseModal from'@/components/modals/BaseModal.vue';import JalaliDatePicker from'@/components/cost/JalaliDatePicker.vue';import{tehranToday}from'@/utils/costControl';const props=defineProps({modelValue:Boolean,overhead:{type:Object,default:null},kinds:{type:Array,default:()=>[]},allocations:{type:Array,default:()=>[]},loading:Boolean,serverError:{type:String,default:''},fieldErrors:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue','submit']),visible=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}),form=reactive({title:'',kind:'fixed',amount:'',allocation_method:'monthly',expense_date:tehranToday(),description:'',is_active:true}),errors=reactive({}),titleInput=ref(null);function clear(){Object.keys(errors).forEach(key=>delete errors[key])}function hydrate(){clear();Object.assign(form,{title:props.overhead?.title||'',kind:props.overhead?.kind||props.kinds[0]?.[0]||'fixed',amount:props.overhead?.amount||'',allocation_method:props.overhead?.allocation_method||props.allocations[0]?.[0]||'monthly',expense_date:props.overhead?.expense_date||tehranToday(),description:props.overhead?.description||'',is_active:props.overhead?.is_active??true});if(props.modelValue)nextTick(()=>titleInput.value?.focus())}function submit(){clear();if(!form.title)errors.title='عنوان را وارد کنید.';if(!form.amount||Number(form.amount)<=0)errors.amount='مبلغ باید بزرگ‌تر از صفر باشد.';if(!form.expense_date)errors.expense_date='تاریخ را انتخاب کنید.';if(!Object.keys(errors).length)emit('submit',{...form,amount:Number(form.amount)})}watch(()=>[props.modelValue,props.overhead,props.kinds,props.allocations],hydrate,{immediate:true,deep:true});watch(()=>props.fieldErrors,value=>{clear();for(const[key,messages]of Object.entries(value||{}))errors[key]=Array.isArray(messages)?messages[0]:messages},{deep:true})</script>
<style scoped>.title h2,.title p{margin:0}.title h2{font-size:1.15rem}.title p{margin-top:3px;color:var(--muted);font-size:.72rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.wide{grid-column:1/-1}label{display:grid;gap:6px;font-size:.78rem;font-weight:700}label>b{color:var(--muted);font-size:.64rem;font-weight:400}input,select,textarea,:deep(.jalali-input){width:100%;min-height:43px;padding:9px 11px!important;border:1px solid var(--border-strong)!important;border-radius:9px!important;background:var(--input)!important;color:var(--text)!important;font:inherit!important;box-sizing:border-box}textarea{resize:vertical}em{color:var(--danger);font-size:.7rem;font-style:normal}.active{display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid var(--border);border-radius:9px}.active span{display:grid;gap:3px}.active small{color:var(--muted);font-size:.65rem;font-weight:400}.active input{width:20px;min-height:20px;accent-color:var(--primary)}.error{margin-bottom:14px;padding:10px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2;color:var(--danger);font-size:.74rem}.primary,.secondary{min-width:110px;padding:10px 14px;border:0;border-radius:9px;font:inherit;font-weight:700}.primary{background:var(--primary);color:#fff}.secondary{background:var(--surface-subtle);color:var(--text)}@media(max-width:600px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
